{"commitMessage":"feat(clients): add search by name or email to client list","files":[{"path":"src/app/(crm)/clientes/page.tsx","content":"import type { Metadata } from "next";
import Link from "next/link";
import { connection } from "next/server";
import { Suspense } from "react";
import { ButtonLink } from "@/components/button";
import { Loading, PageHeader } from "@/components/page-header";
import { EmptyRow, Table, Td, Th, Tr } from "@/components/table";
import { listClients } from "./queries";

export const metadata: Metadata = { title: "Clientes · crm-demo" };

type SearchParams = Promise<{ search?: string | string[] }>;

export default function ClientsPage({
  searchParams,
}: {
  searchParams: SearchParams;
}) {
  return (
    <>
      <PageHeader
        title="Clientes"
        actions={
          <ButtonLink href="/clientes/nuevo" data-testid="new-client-button">
            Nuevo cliente
          </ButtonLink>
        }
      />
      <Suspense fallback={<Loading />}>
        <ClientsContent searchParams={searchParams} />
      </Suspense>
    </>
  );
}

async function ClientsContent({
  searchParams,
}: {
  searchParams: SearchParams;
}) {
  // Read the database at request time, never at build time.
  await connection();
  const params = await searchParams;
  const raw = params.search;
  const search = (Array.isArray(raw) ? raw[0] : raw) ?? "";
  const clients = filterClients(await listClients(), search);
  return (
    <>
      <form
        method="get"
        action="/clientes"
        className="mb-4 flex w-full justify-end"
      >
        <input
          type="text"
          name="search"
          defaultValue={search}
          placeholder="Buscar por nombre o email"
          aria-label="Buscar por nombre o email"
          data-testid="client-search-input"
          className="w-full rounded-md border border-slate-300 bg-white px-3 py-2 text-sm sm:w-72"
        />
      </form>
      <ClientsTable clients={clients} />
    </>
  );
}

function filterClients<T extends { name: string; email: string }>(
  clients: T[],
  search: string,
): T[] {
  const term = search.trim().toLowerCase();
  if (!term) return clients;
  return clients.filter(
    (c) =>
      c.name.toLowerCase().includes(term) ||
      c.email.toLowerCase().includes(term),
  );
}

function ClientsTable({
  clients,
}: {
  clients: Awaited<ReturnType<typeof listClients>>;
}) {
  return (
    <Table data-testid="clients-table">
      <thead>
        <tr>
          <Th>Nombre</Th>
          <Th className="hidden sm:table-cell">NIF</Th>
          <Th className="hidden sm:table-cell">Empresa</Th>
          <Th className="hidden md:table-cell">Email</Th>
          <Th className="hidden md:table-cell">Teléfono</Th>
        </tr>
      </thead>
      <tbody className="divide-y divide-slate-100">
        {clients.length === 0 && (
          <EmptyRow colSpan={5}>Todavía no hay clientes.</EmptyRow>
        )}
        {clients.map((client) => (
          <Tr key={client.id} data-testid="client-row" data-id={client.id}>
            <Td>
              <Link
                href={`/clientes/${client.id}`}
                className="font-medium text-blue-700 hover:underline"
              >
                {client.name}
              </Link>
              <div className="text-xs text-slate-500 sm:hidden">
                {client.company ?? client.email}
              </div>
            </Td>
            <Td className="hidden whitespace-nowrap sm:table-cell">
              {client.nif ?? "—"}
            </Td>
            <Td className="hidden sm:table-cell">{client.company ?? "—"}</Td>
            <Td className="hidden md:table-cell">{client.email}</Td>
            <Td className="hidden whitespace-nowrap md:table-cell">
              {client.phone ?? "—"}
            </Td>
          </Tr>
        ))}
      </tbody>
    </Table>
  );
}
"}],"notes":"He añadido un buscador en /clientes con un formulario GET nativo (Enter envía ?search=...), y la página lo lee vía searchParams dentro de Suspense con connection(), en lugar de useSearchParams/useRouter, para evitar convertir la página en componente cliente y problemas con cacheComponents. El filtrado es insensible a mayúsculas sobre nombre y email. El input va encima de la tabla, alineado a la derecha en escritorio y a ancho completo en móvil, no dentro del PageHeader. Asumo que listClients no cambia; el filtrado se hace en memoria.","evidence":[{"criterion":"c1","hint":"/clientes: input client-search-input vacío y filas client-row"},{"criterion":"c2","hint":"/clientes?search=juan: filas client-row filtradas"},{"criterion":"c3","hint":"placeholder 'Buscar por nombre o email', alineado a la derecha"},{"criterion":"c4","hint":"input w-full en 390 px"}]}
